package com.kovian.finance.debt.api;
import com.kovian.finance.debt.domain.*; import com.kovian.finance.debt.repository.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/debts") public class DebtController {final DebtRepository debts; final DebtInstallmentRepository installments; public DebtController(DebtRepository d,DebtInstallmentRepository i){debts=d;installments=i;} record CreateRequest(UUID ownerId,String name,DebtType debtType,BigDecimal principalAmount,BigDecimal annualInterestRate,LocalDate startDate,LocalDate endDate,int totalInstallments){}
@PostMapping @Transactional public Debt create(@RequestBody CreateRequest r){var start=r.startDate()==null?LocalDate.now():r.startDate();var d=debts.save(new Debt(r.ownerId(),r.name(),r.debtType(),r.principalAmount(),r.annualInterestRate(),start,r.endDate(),r.totalInstallments()));var part=r.principalAmount().divide(BigDecimal.valueOf(r.totalInstallments()),4,RoundingMode.HALF_UP);for(int n=1;n<=r.totalInstallments();n++){var amount=n==r.totalInstallments()?r.principalAmount().subtract(part.multiply(BigDecimal.valueOf(n-1))):part;installments.save(new DebtInstallment(r.ownerId(),d.getId(),n,start.plusMonths(n),amount,BigDecimal.ZERO));}return d;}
@GetMapping public List<Debt> list(@RequestParam UUID ownerId){return debts.findByOwnerIdOrderByName(ownerId);} @GetMapping("/{id}/installments") public List<DebtInstallment> installments(@PathVariable UUID id){return installments.findByDebtIdOrderByDueDate(id);} @PostMapping("/{id}/pay/{installmentId}") @Transactional public void pay(@PathVariable UUID id,@PathVariable UUID installmentId,@RequestParam UUID ownerId){var d=debts.findByIdAndOwnerId(id,ownerId).orElseThrow();var i=installments.findByIdAndOwnerId(installmentId,ownerId).orElseThrow();if(!i.getDebtId().equals(d.getId())||i.getStatus()!=InstallmentStatus.PENDING)throw new IllegalArgumentException("Invalid installment");d.pay(i.getAmount());i.pay(null);}}
